"""Package the browser files as a Python module for Workers deployment."""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
# Cloudflare Python Workers bundle Python modules, so encode the two browser
# assets as string constants imported by src/entry.py.
page = (ROOT / "web/console.html").read_text()
script = (ROOT / "web/console.js").read_text()
(ROOT / "src/console_assets.py").write_text(
    "# Generated by scripts/build_console.py; edit web/ instead.\n"
    f"PAGE = {page!r}\nSCRIPT = {script!r}\n"
)
